import { mkdirSync, writeFileSync } from 'node:fs';

// Task 12: authored screen layouts, deterministic fixtures, and explicit variants.
// The generated artifact is self-contained so it also renders in a Notion HTML embed.
const screens = [];
const add = (id, batch, name, flow, action, target, states, note, body) => screens.push({id,batch,name,flow,action,target,states:states.split('|'),note,body});
const field = (label, value='', type='text') => `<label class="field">${label}<input type="${type}" value="${value}" placeholder="${label}" autocomplete="off"></label>`;
const area = (label,value='') => `<label class="field">${label}<textarea rows="3">${value}</textarea></label>`;
const select = (label,values) => `<label class="field">${label}<select>${values.map(v=>`<option>${v}</option>`).join('')}</select></label>`;
const check = (label,checked=true) => `<label class="check"><input type="checkbox" ${checked?'checked':''}> ${label}</label>`;
const go = (label,id,klass='') => `<button type="button" class="${klass}" data-go="${id}">${label}</button>`;
const state = (label,value) => `<button type="button" data-state="${value}">${label}</button>`;
const row = (title,sub,id,tag='Open') => `<div class="row"><div><strong>${title}</strong><small>${sub}</small></div>${go(tag,id)}</div>`;
const box = (title,body) => `<section class="panel"><h3>${title}</h3>${body}</section>`;
const cols = (...items) => `<div class="columns">${items.join('')}</div>`;
const list = items => `<ul class="checklist">${items.map(v=>`<li>${v}</li>`).join('')}</ul>`;
const table = (heads,rows) => `<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const note = text => `<p class="hint">${text}</p>`;
const tabs = () => `<nav class="tabs" aria-label="Test sections">${go('Build','S09')}${go('Preview','S17')}${go('Share','S20')}${go('Results','S22')}</nav>`;
const resultnav = () => `<nav class="tabs" aria-label="Result sections">${go('Overview','S22')}${go('Tasks','S23')}${go('Paths','S24')}${go('Heatmap','S25')}${go('Sessions','S26')}${go('Findings','S28')}</nav>`;
const context = `<div class="context">Checkout study · Published v1 · All dates · Task 1<br><strong>24 started · 2 technical blocked · 22 eligible</strong></div>`;
const results = body => resultnav()+context+body;
const metrics = () => table(['Metric','Fixture value','Basis'],[['Completion','77.3%','17 successes / 22 eligible'],['Median time','42s','17 successful tasks only'],['P75 / P90','58s / 71s','Same successful-task cohort'],['Misclick','12%','36 derived misclicks / 300 eligible pointers'],['Give up','9.1%','2 / 22 eligible'],['Failure','4.5%','1 / 22 eligible'],['SEQ','5.4 / 7','18 answers · 1 difficult → 7 easy']]);
const frame = (title='Checkout',height='') => `<div class="prototype" ${height?`style="min-height:${height}"`:''}><div class="proto-header">Sample shop <span>Bag (1)</span></div><div class="placeholder" aria-label="Product image placeholder">Product image</div><h3>${title}</h3><p>Canvas bag · 1 item</p><div class="row"><span>Subtotal</span><strong>฿490</strong></div><div class="mock-button">Continue</div><p class="hint">Prototype placeholder</p></div>`;
const seq = () => `<fieldset><legend>โดยรวม งานนี้ง่ายหรือยากเพียงใด?</legend><div class="seq">${[1,2,3,4,5,6,7].map(n=>`<label><input type="radio" name="seq" value="${n}"><span>${n}</span></label>`).join('')}</div><div class="row"><small>1 · ยากมาก</small><small>7 · ง่ายมาก</small></div></fieldset>`;

