function runtime(screens) {
  const byId=Object.fromEntries(screens.map(s=>[s.id,s]));
  const $=id=>document.getElementById(id);
  let current='S03', variant='Default', previewMode=false, taskNumber=1;
  const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const message=(title,body,action='')=>`<div class="notice" role="status"><strong>${title}</strong><p>${body}</p>${action}</div>`;
  const jump=(title,id)=>`<button type="button" data-go="${id}">${title}</button>`;
  const retry=()=>`<button type="button" data-state="${escape(byId[current].states[0])}">Retry / ลองอีกครั้ง</button>`;
  const empty=(title,body,target,label)=>`<div class="empty-state"><h3>${title}</h3><p>${body}</p>${target?jump(label,target):''}</div>`;
  const skeleton=()=>`<div role="status" aria-label="Loading"><p>Loading…</p><div class="skeleton short"></div><div class="skeleton"></div><div class="skeleton big"></div></div>`;
  const matrix={
    'Auth Error':['Could not sign in','Check your credentials or reconnect your Figma account. Your input is preserved.'],
    'Invalid URL':['Check the prototype link','Use a Figma prototype URL. The current link could not be recognized.'],
    'Missing Start':['Select a start frame','Choose the frame participants should see when this task starts.'],
    'Missing Rule':['Success rule required','Choose a success frame before continuing to preview and publish.'],
    'Conflict':['Resolve conflicting rules','Success and failure cannot point at the same frame. Edit the failure rule.'],
    'Invalid Draft':['Draft needs attention','Fix the required task settings before starting a preview.'],
    'Provider Blocked':['Prototype unavailable','Fix prototype sharing or reconnect Figma before preview.'],
    'Publish Blocked':['Publishing is blocked','The draft has unresolved requirements. No published version will be created.'],
    'Blocked':['Publishing is blocked','Participant access did not pass. No new published version was created.'],
    'Version Changed':['Prototype changed since preview','Select the new Figma version and rerun preview and publish checks. The previous published version stays unchanged.'],
    'Private/Login Required':['Participant login required','Update prototype sharing in Figma, then check access again.'],
    'Password':['Prototype is password protected','Resolve participant access with the study owner. This is a technical issue, not a failed task.'],
    'Provider Error':['Provider unavailable','The prototype service did not respond. This is not a usability failure.'],
    'Unsupported':['Start point unavailable','This prototype capability is not supported. Choose a supported prototype.'],
    'Unsupported Evidence':['Path evidence unavailable','The provider did not supply usable screen evidence. No path or backtrack counts are inferred.'],
    'Unsupported Provider/Transform':['Heatmap unavailable','Canonical frame mapping is not available. Clicks are not plotted at guessed viewport coordinates.'],
    'Technical-blocked Warning':['2 sessions blocked by technical issues','Excluded from the 22 eligible task sessions. Review operational issues separately from usability findings.'],
    'Technical-blocked Context':['Technical issues reported separately','Baseline: 2 / 24 started. Retest: 2 / 27 started. Both are excluded from completion denominators.'],
    'Low Sample':['Small sample: interpret cautiously','Use the displayed counts as descriptive evidence. No statistical significance is claimed.'],
    'Partial Data':['Results are still processing','Accepted data is being aggregated. Unavailable values stay — until the cohort is ready.'],
    'Redacted Fields':['Restricted fields hidden','Participant identifiers and open feedback are hidden for this access level.'],
    'Evidence Deleted':['Evidence unavailable / deleted','The source was removed by a privacy operation. Raw content and snapshots are no longer shown.'],
    'Change Pending':['Policy change pending','90 days remains active until an authorized, supported policy change is applied.'],
    'Permission Restricted':['Read-only access','Your role can view the study but cannot edit, preview or publish.'],
    'Restricted':['Access restricted','Your role cannot access participant details or change this setting.'],
    'Permission Denied':['Admin access required','Workspace settings can only be changed by an authorized Owner or Admin.']
  };
  const blockedStates=['Auth Error','Invalid URL','Missing Start','Missing Rule','Conflict','Invalid Draft','Provider Blocked','Publish Blocked','Blocked','Version Changed','Private/Login Required','Password','Provider Error','Unsupported','Permission Restricted','Restricted','Permission Denied'];
  function view(s,v){
    let body=s.body,action=s.action,target=s.target,disabled=false;
    const loading=/^(Loading|Submit Loading|Connecting|Validating|Checking|Accepting|Provider Loading|Processing)$/.test(v);
    if(loading){body=skeleton();disabled=true;action=v+'…';}
    else if(v==='Empty'){
      const defs={S03:['Create your first project','Keep related studies and findings together.','S05','Create project'],S04:['No projects yet','Create a project to start a prototype study.','S05','Create project'],S07:['No tests yet','Create a prototype test in this project.','S08','Create test'],S10:['Add your prototype','Paste a Figma prototype link to continue.',null,''],S21:['No published results','Publish a study and collect participant sessions first.','S19','Review publish'],S26:['No sessions match','Clear filters or wait for participant sessions.',null,''],S28:['No findings yet','Review evidence or create your first finding.','S29','Create finding'],S31:['No participant data','Participant data appears after consent and study activity.',null,'']};
      const d=defs[s.id]||['Nothing here yet','Complete the preceding step.',null,''];body=empty(...d)+(s.id==='S10'?s.body:'');
    } else if(v==='Empty Tests'){body=empty('No tests in this project','Create the first prototype study.','S08','Create test');}
    else if(v==='Empty Findings'){body=empty('No findings in this project','Inspect study results to find supporting evidence.','S22','View results');}
    else if(['No Data','No Eligible Sessions','No Path Data','No Clicks','No Baseline'].includes(v)){
      const d={
        'No Data':['No participant results yet','Completion — · Time — · Eligible n=0. Zero collected data does not mean zero success.','S20','View sharing'],
        'No Eligible Sessions':['No eligible task sessions','2 started − 2 technical blocked = 0 eligible. Completion and time are —.',null,''],
        'No Path Data':['No path evidence','There are no usable screen transitions for this selection.',null,''],
        'No Clicks':['No pointer evidence','No clicks are plotted. Check the selected frame and filters.',null,''],
        'No Baseline':['Choose a baseline','Compare published study versions after selecting a baseline.','S21','Choose study']};
      body=empty(...d[v]);disabled=!['No Data','No Baseline'].includes(v);
    } else if(/Validation/.test(v)){
      body=message('Check the highlighted fields','Required information is missing. Your other input is preserved.')+s.body;
      disabled=true;
    } else if(v==='Error'){
      body=message('This step could not be completed','Your previous work is preserved. Try again when the connection is available.',retry())+(s.id==='S32'?'':s.body);disabled=true;
    } else if(matrix[v]){
      const hide=['Unsupported','Unsupported Evidence','Unsupported Provider/Transform','Restricted','Permission Denied','Evidence Deleted','Redacted Fields','Private/Login Required','Password','Provider Error','Blocked','Version Changed'].includes(v);
      body=message(...matrix[v])+(hide?'':s.body);disabled=blockedStates.includes(v)||v==='Evidence Deleted';
      if(v==='Partial Data')body=message(...matrix[v])+empty('Aggregation in progress','Completion — · Time — · eligible count pending. Refresh after processing.',null,'');
      if(s.id==='S29'&&v==='Evidence Deleted'){body=message(...matrix[v])+`<label class="field">Finding title<input value="Shipping cost is hard to find"></label><label class="field">Researcher recommendation<textarea>Show shipping information earlier.</textarea></label>`;disabled=false;}
      if(s.id==='S19'&&['Blocked','Version Changed'].includes(v))body+=`<ul class="checklist"><li>Participant access: recheck required</li><li>Figma version pin: pending revalidation</li><li>Consent and rules: retained in draft</li><li>Published version: not created</li></ul>`+jump('Return to prototype checks','S11');
      if(s.id==='S11'&&['Private/Login Required','Password','Provider Error'].includes(v))body+=jump('Edit prototype link','S10');
    }
    if(s.id==='S07'&&['Draft','Published','Closed'].includes(v))body=`<p>Filter: <strong>${v}</strong></p><div class="row"><div><strong>Checkout study</strong><small>${v==='Draft'?'Draft · Needs validation':v==='Published'?'v1 · Collecting':'v1 · Closed to new participants'}</small></div>${jump(v==='Draft'?'Build':'Results',v==='Draft'?'S09':'S22')}</div>`;
    if(['Search/Filter','Filter','Search'].includes(v))body=message('No matches for “sample query”','Change the search or clear the filter to see all items.',`<button data-state="${escape(s.states[0])}">Clear filters</button>`)+`<label class="field">Search<input value="sample query"></label>`;
    if(v==='Filtered')body=message('Filter: derived misclicks','36 eligible misclicks study-wide · Showing frame 1:3 only. Cluster counts are illustrative.')+s.body;
    if(s.id==='S09'&&v==='Incomplete')body=message('2 required items missing','Connect a prototype and choose a success rule.',jump('Fix prototype','S10')+jump('Fix rules','S14'))+s.body;
    if(s.id==='S13'&&v==='Reorder')body=message('Reorder tasks','Use Move up / Move down with a keyboard. Start points and rules stay attached to each task.')+`<div class="row"><strong>1 · Checkout</strong><button data-demo="Moved Checkout down (wireframe simulation)">Move down</button></div><div class="row"><strong>2 · Order status</strong><button data-demo="Moved Order status up (wireframe simulation)">Move up</button></div>`;
    if(s.id==='S14'&&v==='Failure Rule')body=message('Failure rule selected','Reach payment-error frame 1:6 → failed. Technical access errors are excluded.')+s.body;
    if(s.id==='S14'&&v==='Timeout')body=message('Timeout rule','180 seconds from task start. First terminal outcome wins.')+s.body;
    if(s.id==='S15'&&v==='Open Feedback')body=`<label class="field">Open feedback prompt<textarea>What made this task easy or difficult?</textarea></label><label class="check"><input type="checkbox"> Require answer</label><p class="hint">Restricted participant content · Do not request personal information.</p>`;
    if(v==='Optional/Required')body=message('Required response setting','SEQ required; open feedback optional. Technical-blocked tasks bypass usability SEQ.')+s.body;
    if(s.id==='S16'&&v==='Warning')body=message('Review before publishing','Optional open feedback is disabled. Required validation checks passed.')+s.body;
    if(s.id==='S18'&&v==='Success Simulation'){body=message('Simulated task terminal','Preview-only indirect success. No production event or result is created.',jump('Preview feedback','P06'));action='Return to builder';target='S09';}
    if(s.id==='S18'&&v==='Exit Preview'){body=message('Leave preview?','The study draft remains saved.',jump('Back to build','S09'));action='Keep previewing';target='S18';}
    if(s.id==='S20'&&v==='Copy Link')body=message('Illustrative link copied','This is a non-routable example.invalid link, not a live study. No clipboard write occurs in this review.')+s.body;
    if(s.id==='S20'&&v==='Closed')body=message('Study closed','Existing results are retained. New participants see Test unavailable.',jump('Review unavailable state','P09'));
    if(s.id==='S20'&&v==='Republish/New Version'){body=message('New draft from v1','Update the prototype and run access, preview, and publish checks again. v1 remains immutable.');action='Edit new draft';target='S09';}
    if(s.id==='S27'&&v==='Technical Blocked')body=message('Technical blocked · excluded','Prototype login requirement prevented task execution. This is not a failed task and no SEQ is required.');
    if(s.id==='S28'&&v==='Resolved')body=message('Resolved findings','Shipping cost is hard to find · Resolved after retest review.',jump('Compare evidence','S30'));
    if(s.id==='S29'&&v==='Evidence Linked')body=message('Evidence linked','Checkout v1 · Task 1 · Frame 1:3 · sample-01. The link preserves published-version context.')+s.body;
    if(s.id==='S32'&&v==='Complete'){body=message('Deletion complete','Raw events, answers, identifiers and derived/cache data in scope were removed or recomputed. Linked findings now show evidence unavailable.');action='Back to participant data';target='S31';}
    if(s.id==='S34'&&v==='Invite/Edit')body=message('Member access editor','Product access and workspace administration are separate. No invitations are sent by this wireframe.')+s.body;
    if(s.id==='S35'&&v==='Connected'){body=message('Figma connected','Metadata access is available. Check participant sharing separately for each study.')+s.body;action='Import prototype';target='S10';}
    if(s.id==='P02'&&v==='Declined'){body='<h2>คุณเลือกไม่เข้าร่วม</h2><p>ยังไม่ได้เริ่มเก็บพฤติกรรมการทดสอบ คุณปิดหน้านี้ได้เลย</p>';action='';}
    if(s.id==='P03'){body=s.body.replace('งาน 1 จาก 2',`งาน ${v==='Multi-task Progress'?2:taskNumber} จาก 2`);if(taskNumber===2||v==='Multi-task Progress')body=body.replace('เลือกซื้อกระเป๋า','ตรวจสอบคำสั่งซื้อ').replace('ลองหากระเป๋าผ้าแล้วสั่งซื้อสินค้าให้เรียบร้อย โดยทำตามวิธีที่คุณจะใช้ตามปกติ','ลองตรวจสอบสถานะคำสั่งซื้อล่าสุดด้วยวิธีที่คุณจะใช้ตามปกติ');}
    if(s.id==='P04'&&v==='Buffering')body=message('การเชื่อมต่อไม่เสถียร','เก็บความคืบหน้าไว้และกำลังรอส่งข้อมูล การเชื่อมต่อสะดุดยังไม่ถือว่าออกจากงาน',jump('ดูหน้ากู้คืน','P12'))+s.body;
    if(s.id==='P04'&&taskNumber===2)body=body.replace('งาน 1 จาก 2','งาน 2 จาก 2').replace('หากระเป๋าผ้าแล้วลองสั่งซื้อให้เรียบร้อย','ลองตรวจสอบสถานะคำสั่งซื้อล่าสุด');
    if(s.id==='P05'&&v==='Cancel'){body='<h2>กลับไปทำงานเดิม</h2><p>ยังไม่ได้ยืนยันหยุดงาน ความคืบหน้าและเวลาเดิมยังคงอยู่</p>';action='ทำงานต่อ';target='P04';}
    if(s.id==='P06'&&v==='Open Feedback')body=`<h2>ความคิดเห็นเพิ่มเติม</h2><label class="field">มีอะไรอยากบอกเรา? (ไม่บังคับ)<textarea rows="5"></textarea></label><p>โปรดไม่ใส่ข้อมูลส่วนตัว</p>`;
    if(s.id==='P07'&&taskNumber===2&&v==='Ready'){body='<h2>บันทึกความคิดเห็นแล้ว</h2><p>เสร็จครบ 2 จาก 2 งาน</p>';action='จบการทดสอบ';target='P08';}
    if(s.id==='P09'){const labels={Invalid:'ลิงก์ไม่ถูกต้อง',Expired:'ลิงก์หมดอายุแล้ว',Closed:'แบบทดสอบปิดรับแล้ว'};body=`<h2>${labels[v]||labels.Invalid}</h2><p>กรุณาติดต่อผู้ที่เชิญคุณเพื่อขอลิงก์ที่ใช้งานได้ คุณปิดหน้านี้ได้</p>`;action='';}
    if(s.id==='P10'){const labels={'Login Required':'ต้นแบบขอให้เข้าสู่ระบบ','Password':'ต้นแบบติดรหัสผ่าน','Permission':'ยังไม่มีสิทธิ์เปิดต้นแบบ','Provider Error':'บริการต้นแบบไม่ตอบสนอง'};body=`<h2>${labels[v]}</h2><p>ปัญหานี้ไม่ได้เกิดจากการทำงานของคุณ กรุณาแจ้งผู้จัดการศึกษา</p><div class="notice">รหัสอ้างอิง: sample-reference-01</div><p>หยุดที่นี่ได้โดยไม่ต้องตอบคำถามความยากง่ายของงานนี้</p>`;action='';}
    if(s.id==='P11'&&v==='Continue per config'){body='<h2>ขอบคุณที่ลองทำงานนี้</h2><p>งานนี้ไม่มีคำถามหลังทำ ไปดูงานถัดไปได้เมื่อพร้อม</p>';action='งานถัดไป';target='P07';}
    if(s.id==='P12'&&v==='Resume Success'){body='<h2>เชื่อมต่อได้แล้ว</h2><p>กลับไปทำงานเดิมต่อจากความคืบหน้าที่บันทึกไว้</p>';action='ทำงานต่อ';target='P04';}
    if(s.id==='P12'&&v==='Resume Failed'){body='<h2>กลับไปทำงานเดิมไม่ได้</h2><p>พ้นช่วงเวลาที่กู้คืนได้แล้ว กรุณาแจ้งผู้จัดการศึกษาพร้อมรหัสอ้างอิง sample-reference-01</p>';action='';}
    if(/^S2[2-7]$/.test(s.id)&&!body.includes('class="context"'))body='<div class="context">Checkout study · Published v1 · Task 1</div>'+body;
    return {body,action,target,disabled};
  }
  function show(id,st){
    if(!byId[id])return;
    current=id;const s=byId[id];variant=s.states.includes(st)?st:s.states[0];
    $('screen-select').value=id;
    $('state-select').innerHTML=s.states.map(v=>`<option${v===variant?' selected':''}>${escape(v)}</option>`).join('');
    document.querySelectorAll('.catalog [data-go]').forEach(el=>{el.classList.toggle('active',el.dataset.go===id);if(el.dataset.go===id)el.closest('details').open=true;});
    const v=view(s,variant), participant=id.startsWith('P'),entry=['S01','S02'].includes(id);
    $('canvas').className='canvas'+(participant?' participant':entry?' entry':'');
    $('caption').textContent=`${id} · ${s.name}`;
    $('context-label').textContent=`Flow ${s.flow} · ${variant} · ${participant?'Mobile-first':'Researcher desktop / responsive'}`;
    const navigation=[['Home','S03'],['Projects','S04'],['Results','S21'],['Participants','S31'],['Settings','S33']];
    const appnav=`<nav class="appnav" aria-label="Workspace navigation">${navigation.map(([label,target])=>`<button data-go="${target}" class="${id===target?'active':''}">${label}</button>`).join('')}</nav>`;
    const content=`<main class="screen" id="screen-content" tabindex="-1"><div class="screenhead"><div><small>${entry?'Workspace access':participant?'': 'Research team / Shop experience'}</small><h1>${s.name}</h1></div><span class="badge">${escape(variant)}</span></div><div id="screen-body">${v.body}</div><div class="actions">${v.action?`<button class="primary" data-primary data-go="${v.target}" ${v.disabled?'disabled':''}>${v.action}</button>`:''}${!participant&&!entry?jump('Back to project','S06'):''}</div>${!participant?'<p class="sample-label">Wireframe fixture · No live data or external actions</p>':''}</main>`;
    $('canvas').innerHTML=`<div class="printmeta" style="display:none">${s.id} · ${s.name} · Flow ${s.flow} · ${variant}</div><div class="appbar"><strong>${participant?'ทดสอบประสบการณ์': 'UT Platform'}</strong><span>${previewMode?'Preview only · No production results':'Research team'}</span></div>${previewMode&&participant?'<div class="notice">Preview only · No production results <button data-go="S09">Exit preview</button></div>':''}${participant||entry?content:`<div class="appbody">${appnav}${content}</div>`}`;
    $('annotation').innerHTML=`<div><strong>Interaction / Flow ${s.flow}</strong><p>${s.note}</p><p>Primary: ${escape(v.action||'End state — close page')}${v.action?' → '+v.target:''}</p></div><div><strong>State coverage (${s.states.length})</strong><p>${s.states.join(' · ')}</p><p>Review artifact: navigation and state simulation only. No real login, tracking, publishing, invitations or deletion.</p></div>`;
    $('runner-demo').hidden=id!=='P04';$('finish-demo').hidden=id!=='P07';
    if(/Validation/.test(variant)){
      const input=$('screen-body').querySelector('input:not([type=checkbox]):not([type=radio]),textarea');
      if(input){input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby','inline-error');input.insertAdjacentHTML('afterend','<span id="inline-error" class="inline-error">This field is required / กรุณากรอกข้อมูล</span>');}
      else if(id==='P06')$('screen-body').insertAdjacentHTML('afterbegin','<p class="inline-error" role="alert">กรุณาเลือกคะแนน 1–7 ก่อนส่ง</p>');
    }
    if(['Permission Restricted','Restricted','Permission Denied'].includes(variant))$('screen-body').querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=true);
    $('review-status').textContent=`${id} ${s.name}, ${variant}`;
    try{history.replaceState(null,'',`#${id}/${encodeURIComponent(variant)}`);}catch{}
  }
  function toast(text){$('toast').textContent=text;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').textContent='',3500);}
  document.addEventListener('click',e=>{
    const target=e.target.closest('button');if(!target||target.disabled)return;
    if(target.dataset.state){show(current,target.dataset.state);return;}
    if(target.dataset.demo){toast(target.dataset.demo);return;}
    if(target.dataset.go){
      const next=target.dataset.go;
      if(target.hasAttribute('data-primary')){
        if(current==='S32'&&variant==='Confirm Scope'){const acknowledged=$('screen-body').querySelector('input[type=checkbox]');if(!acknowledged?.checked){toast('Confirm the deletion scope checkbox first (demo only).');return;}show('S32','Processing');return;}
        if(current==='S35'&&variant==='Disconnected'){show('S35','Connected');return;}
        if(current==='S36'){show('S36','Change Pending');return;}
        if(['S33','S34','P08'].includes(current)){toast(current==='P08'?'รหัสอ้างอิง: sample-reference-01':'Saved in this wireframe simulation only.');return;}
        if(current==='P12'){show('P12','Resume Success');return;}
        if(current==='P06'&&variant!=='Open Feedback'&&!$('screen-body').querySelector('input[name=seq]:checked')){show('P06','Validation');return;}
        if(['S01','S02','S05','S08','S10','S13','S29'].includes(current)){
          const inputs=[...$('screen-body').querySelectorAll('input:not([type=checkbox]),textarea')];
          const first=inputs[0];if(first&&!first.value.trim()){const invalid=byId[current].states.find(v=>/Validation|Invalid URL|Auth Error/.test(v));if(invalid)show(current,invalid);return;}
        }
      }
      if(current==='S17'&&next==='S18')previewMode=true;
      if(!next.startsWith('P')&&next!=='S18')previewMode=false;
      if(current==='P02'&&next==='P03')taskNumber=1;
      if(current==='P07'&&next==='P03')taskNumber=2;
      show(next);$('screen-content').focus({preventScroll:true});
    }
  });
  document.addEventListener('input',e=>{
    if(!e.target.closest('#screen-body')||!/Validation/.test(variant))return;
    const valid=current==='P06'?!!$('screen-body').querySelector('input[name=seq]:checked'):!!$('screen-body').querySelector('input:not([type=checkbox]):not([type=radio]),textarea')?.value.trim();
    if(valid){const primary=$('canvas').querySelector('[data-primary]');if(primary)primary.disabled=false;$('screen-body').querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));$('screen-body').querySelector('.inline-error')?.remove();}
  });
  $('screen-select').innerHTML=screens.map(s=>`<option value="${s.id}">${s.id} · ${s.name}</option>`).join('');
  $('screen-select').addEventListener('change',e=>{previewMode=false;taskNumber=1;show(e.target.value);});
  $('state-select').addEventListener('change',e=>show(current,e.target.value));
  $('viewport-select').addEventListener('change',e=>$('stage').classList.toggle('review-mobile',e.target.value==='mobile'));
  $('prev').onclick=()=>show(screens[(screens.findIndex(s=>s.id===current)+47)%48].id);
  $('next').onclick=()=>show(screens[(screens.findIndex(s=>s.id===current)+1)%48].id);
  $('print').onclick=()=>window.print();
  $('runner-demo').onclick=()=>show('P06');$('finish-demo').onclick=()=>show('P08');
  const groups={A:'Core shell + entry',B:'Test builder',C:'Preview / publish',D:'Analytics',E:'Findings / retest',F:'Participant runner',G:'Privacy / settings'};
  $('catalog').innerHTML=Object.entries(groups).map(([batch,label])=>`<details ${batch==='A'?'open':''}><summary>${batch} · ${label}</summary>${screens.filter(s=>s.batch===batch).map(s=>`<button data-go="${s.id}"><span>${s.id}</span>${s.name}</button>`).join('')}</details>`).join('');
  const hash=location.hash.slice(1).split('/');show(byId[hash[0]]?hash[0]:'S03',hash[1]?decodeURIComponent(hash[1]):undefined);
}

const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>UT Platform · Task 12 Wireframes</title><style>${style}</style></head><body>
<header class="reviewbar"><strong>UT Platform / Wireframes</strong><span>Task 12 · 48 screens · Grayscale · Review artifact · Sample data only</span></header>
<section class="reviewtools" aria-label="Wireframe review controls"><label>Screen<select id="screen-select"></select></label><label>State<select id="state-select"></select></label><label>Viewport<select id="viewport-select"><option value="desktop">Responsive / Desktop</option><option value="mobile">Mobile · 390px</option></select></label><div class="grow"></div><button id="prev">← Previous</button><button id="next">Next →</button><button id="print">Print screen</button><button id="runner-demo" hidden>Review: simulate task end</button><button id="finish-demo" hidden>Review: complete study</button></section>
<div class="workspace"><aside class="catalog" id="catalog" aria-label="Screen catalog"></aside><div class="stage" id="stage"><div class="caption"><strong id="caption"></strong><span id="context-label"></span></div><div class="canvas" id="canvas"></div><aside class="annotation" id="annotation" aria-label="Design annotations"></aside></div></div><div class="toast" id="toast" role="status"></div><span id="review-status" role="status" style="position:absolute;width:1px;height:1px;overflow:hidden"></span>
<script>(${runtime.toString()})(${JSON.stringify(screens).replace(/</g,'\\u003c')});</script></body></html>`;
mkdirSync('public/wireframes',{recursive:true});
writeFileSync('public/wireframes/index.html',html);
writeFileSync('public/wireframes/coverage.json',JSON.stringify(screens.map(({body,...s})=>s),null,2)+'\n');
console.log(`Generated ${screens.length} screens / ${screens.reduce((n,s)=>n+s.states.length,0)} explicit states / ${Buffer.byteLength(html)} bytes.`);
